#include <stdio.h>

int main(void) {
  int count = 0;
  double price = 0.0;
  if (scanf("%d %lf", &count, &price) != 2) {
    puts("input-error");
    return 1;
  }
  double total = count * price;
  printf("count=%d,total=%.2f\n", count, total);
  return 0;
}

#include <stdio.h>
int main(void) {
  int a, b, c;
  if (scanf("%d %d %d", &a, &b, &c) != 3) return 1;
  double average = (a + b + c) / 3;
  printf("average=%.2f\n", average);
  return 0;
}

#include <stdio.h>
int main(void) {
  int hours, minutes, seconds;
  if (scanf("%d %d %d", &hours, &minutes, &seconds) != 3) return 1;
  if (hours < 0 || minutes < 0 || minutes > 59 || seconds < 0 || seconds > 59) return 1;
  int total = hours * 3600 + minutes * 60 + seconds;
  printf("total_seconds=%d,clock=%02d:%02d:%02d\n", total, hours, minutes, seconds);
  return 0;
}

